from datetime import datetime
import pytz
import re
from faker import Faker

def task_func(epoch_milliseconds, seed=0, timezones=["UTC"]):
    fake = Faker()
    fake.seed_instance(seed)

    system_tz = datetime.now().astimezone().tzinfo or pytz.UTC
    event_dt = datetime.fromtimestamp(epoch_milliseconds / 1000.0, tz=system_tz)

    event_name = fake.catch_phrase()

    if timezones is None:
        requested_timezones = []
    elif isinstance(timezones, str):
        requested_timezones = [timezones]
    else:
        requested_timezones = list(timezones)

    offset_pattern = re.compile(r"^UTC([+-])(\d{2}):(\d{2})$")
    valid_timezones = []

    for tz in requested_timezones:
        if not isinstance(tz, str):
            continue
        if tz in pytz.all_timezones:
            valid_timezones.append(tz)
            continue
        match = offset_pattern.match(tz)
        if match:
            _, hours_str, minutes_str = match.groups()
            hours = int(hours_str)
            minutes = int(minutes_str)
            if hours <= 23 and minutes <= 59:
                valid_timezones.append(tz)

    if not valid_timezones:
        chosen_timezone_name = "UTC"
        chosen_tzinfo = pytz.timezone("UTC")
    else:
        chosen_timezone_name = fake.random_element(valid_timezones)
        match = offset_pattern.match(chosen_timezone_name)
        if match:
            sign, hours_str, minutes_str = match.groups()
            total_minutes = int(hours_str) * 60 + int(minutes_str)
            if sign == "-":
                total_minutes = -total_minutes
            chosen_tzinfo = pytz.FixedOffset(total_minutes)
        else:
            chosen_tzinfo = pytz.timezone(chosen_timezone_name)

    schedule_dt = event_dt.astimezone(chosen_tzinfo)

    schedule = {
        "date": schedule_dt.date().isoformat(),
        "time": schedule_dt.time().replace(microsecond=0).isoformat(),
        "timezone": chosen_timezone_name,
    }

    return {event_name: [schedule]}
